CREATE OR REPLACE FUNCTION public.update_form_drafts_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    NEW.last_accessed_at = NOW();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_password_strength(password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    result JSONB;
    has_upper BOOLEAN;
    has_lower BOOLEAN;
    has_number BOOLEAN;
    has_special BOOLEAN;
    length_check BOOLEAN;
BEGIN
    -- Check password requirements
    has_upper := password ~ '[A-Z]';
    has_lower := password ~ '[a-z]';
    has_number := password ~ '[0-9]';
    has_special := password ~ '[^A-Za-z0-9]';
    length_check := length(password) >= 8;
    
    result := jsonb_build_object(
        'is_valid', has_upper AND has_lower AND has_number AND has_special AND length_check,
        'has_upper', has_upper,
        'has_lower', has_lower,
        'has_number', has_number,
        'has_special', has_special,
        'length_check', length_check,
        'length', length(password)
    );
    
    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.convert_anonymous_to_authenticated(fingerprint_text text, user_id_uuid uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    rows_affected INTEGER := 0;
BEGIN
    -- Validate inputs
    IF fingerprint_text IS NULL OR trim(fingerprint_text) = '' THEN
        RAISE EXCEPTION 'Fingerprint cannot be null or empty';
    END IF;

    IF user_id_uuid IS NULL THEN
        RAISE EXCEPTION 'User ID cannot be null';
    END IF;

    -- Update user_tracking
    UPDATE public.user_tracking 
    SET 
        user_id = user_id_uuid,
        is_anonymous = false,
        updated_at = NOW()
    WHERE fingerprint = fingerprint_text;
    
    -- Update anonymous_users
    UPDATE public.anonymous_users 
    SET 
        converted_to_user_id = user_id_uuid,
        converted_at = NOW(),
        updated_at = NOW()
    WHERE fingerprint = fingerprint_text;
    
    -- Get total rows affected
    GET DIAGNOSTICS rows_affected = ROW_COUNT;
    
    -- Log the conversion
    IF rows_affected > 0 THEN
        RAISE NOTICE 'Successfully converted anonymous user with fingerprint: %', fingerprint_text;
        RETURN TRUE;
    ELSE
        RAISE NOTICE 'No records found to convert for fingerprint: %', fingerprint_text;
        RETURN FALSE;
    END IF;
END;
$function$
